const H={ apikey:$env.SUPABASE_SERVICE_ROLE_KEY, Authorization:'Bearer '+$env.SUPABASE_SERVICE_ROLE_KEY };
const HW={ ...H, 'Content-Type':'application/json', Prefer:'return=representation' };
const get=(p)=>this.helpers.httpRequest({method:'GET',url:SB+p,headers:H,json:true});
const post=(p,b)=>this.helpers.httpRequest({method:'POST',url:SB+p,headers:HW,body:b,json:true});
const patch=(p,b)=>this.helpers.httpRequest({method:'PATCH',url:SB+p,headers:HW,body:b,json:true});
const ctx=$('Context Loader').first().json.contextBundle;   // org-scoped context (implicit org_id)
const org=ctx.org_id;
const _raw=(typeof query!=='undefined')?query:{}; let a; if(typeof _raw==='string'){ try{ a=JSON.parse(_raw||'{}'); }catch(e){ a={ input:_raw }; } } else { a=_raw||{}; } if(typeof a!=='object'||a===null) a={ input:String(a) };
const enc=encodeURIComponent;
const areas=await get('service_areas?org_id=eq.'+org+'&select=*');
const hay=((a.address||'')+' '+(a.region||'')+' '+(a.zip||'')).toLowerCase();
const match=(arr)=>arr.find(x=>(x.region&&hay.includes(x.region.toLowerCase()))||((x.zips||[]).some(z=>a.zip&&String(a.zip).includes(z))));
const deny=match((areas||[]).filter(x=>x.mode==='deny'));
if(deny) return JSON.stringify({ in_area:false, matched:'deny', region:deny.region, uncertain:false });
const serve=match((areas||[]).filter(x=>x.mode==='serve'));
if(serve) return JSON.stringify({ in_area:true, matched:'serve', region:serve.region, uncertain:false });
return JSON.stringify({ in_area:false, matched:'none', region:null, uncertain:true });

const SB=$env.SUPABASE_URL+'/rest/v1/';
const H={ apikey:$env.SUPABASE_SERVICE_ROLE_KEY, Authorization:'Bearer '+$env.SUPABASE_SERVICE_ROLE_KEY };
const HW={ ...H, 'Content-Type':'application/json', Prefer:'return=representation' };
const get=(p)=>this.helpers.httpRequest({method:'GET',url:SB+p,headers:H,json:true});
const post=(p,b)=>this.helpers.httpRequest({method:'POST',url:SB+p,headers:HW,body:b,json:true});
const patch=(p,b)=>this.helpers.httpRequest({method:'PATCH',url:SB+p,headers:HW,body:b,json:true});
const ctx=$('Context Loader').first().json.contextBundle;   // org-scoped context (implicit org_id)
const org=ctx.org_id;
const _raw=(typeof query!=='undefined')?query:{}; let a; if(typeof _raw==='string'){ try{ a=JSON.parse(_raw||'{}'); }catch(e){ a={ input:_raw }; } } else { a=_raw||{}; } if(typeof a!=='object'||a===null) a={ input:String(a) };
const enc=encodeURIComponent;
const TZ=(ctx.business&&ctx.business.timezone)||'America/New_York';
const SLOT_H=2, MAX_DAYS=14, MAX_SLOTS=15, DAY=86400000; let PER_DAY=3;
const dtf=new Intl.DateTimeFormat('en-US',{timeZone:TZ,hourCycle:'h23',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'});
const offMin=(d)=>{ const p={}; for(const x of dtf.formatToParts(d)) p[x.type]=x.value; return (Date.UTC(+p.year,+p.month-1,+p.day,(+p.hour)%24,+p.minute,+p.second)-Math.floor(d.getTime()/1000)*1000)/60000; };
const localParts=(d)=>{ const t=new Date(d.getTime()+offMin(d)*60000); return { y:t.getUTCFullYear(), m:t.getUTCMonth(), d:t.getUTCDate(), dow:t.getUTCDay() }; };
const toUtc=(y,m,d,h,mi)=>{ const g=new Date(Date.UTC(y,m,d,h,mi)); const r=new Date(g.getTime()-offMin(g)*60000); return new Date(g.getTime()-offMin(r)*60000); };
const ymd=(p)=>p.y+'-'+String(p.m+1).padStart(2,'0')+'-'+String(p.d).padStart(2,'0');
const fmtDay=new Intl.DateTimeFormat('en-US',{timeZone:TZ,weekday:'short',month:'short',day:'numeric'});
const fmtTime=new Intl.DateTimeFormat('en-US',{timeZone:TZ,hour:'numeric',minute:'2-digit'});
const now=new Date();
const parseTs=(v)=>{ if(!v) return null; const t=String(v).trim(); let m=t.match(/^(\d{4})-(\d{2})-(\d{2})$/); if(m) return toUtc(+m[1],+m[2]-1,+m[3],0,0); m=t.match(/^(\d{4})-(\d{2})-(\d{2})[T ](\d{1,2}):(\d{2})(?::\d{2}(?:\.\d+)?)?(?:Z|[+-]00:?00)?$/); if(m) return toUtc(+m[1],+m[2]-1,+m[3],+m[4],+m[5]); const d=new Date(t); return isNaN(d.getTime())?null:d; };
const dayStart=(d)=>{ const p=localParts(d); return toUtc(p.y,p.m,p.d,0,0); };
let ws=parseTs(a.window_start); let we=parseTs(a.window_end);
if(ws) ws=dayStart(ws); if(we){ const p=localParts(we); we=toUtc(p.y,p.m,p.d,23,59); }
if(!ws||ws<now) ws=now;
if(!we||we<=ws) we=a.window_start&&!a.window_end?(()=>{ const p=localParts(ws); return toUtc(p.y,p.m,p.d,23,59); })():new Date(ws.getTime()+7*DAY);
if(we.getTime()-ws.getTime()>MAX_DAYS*DAY) we=new Date(ws.getTime()+MAX_DAYS*DAY);
if(we.getTime()-ws.getTime()<=2*DAY) PER_DAY=6;
let cat=a.category||null;
if(!cat&&a.service_id){ const s=(ctx.services_offered||[]).find(x=>x.id===a.service_id); if(s) cat=s.category; }
const hours=await get('business_hours?org_id=eq.'+org+'&select=*');
const techs=await get('technicians?org_id=eq.'+org+"&status=eq.available&select=*");
const eligible=(techs||[]).filter(t=>!cat||(t.skills||[]).includes(cat));
const existing=await get('appointments?org_id=eq.'+org+'&status=in.(booked,requested)&scheduled_at=gte.'+enc(new Date(ws.getTime()-SLOT_H*3600000).toISOString())+'&scheduled_at=lte.'+enc(we.toISOString())+'&select=scheduled_at,technician_id');
const busy=(id,s,e)=>(existing||[]).some(x=>{ if(x.technician_id!==id) return false; const xs=new Date(x.scheduled_at).getTime(); return xs<e.getTime()&&xs+SLOT_H*3600000>s.getTime(); });
const slots=[]; const closed_days=[]; let total=0;
const sp=localParts(ws);
for(let i=0;i<=MAX_DAYS;i++){
  const noon=toUtc(sp.y,sp.m,sp.d+i,12,0);
  if(noon.getTime()>we.getTime()+DAY) break;
  const p=localParts(noon); const ds=ymd(p);
  const hrow=(hours||[]).find(h=>h.day_of_week===p.dow);
  if(!hrow||!hrow.open_time||!hrow.close_time||(hrow.closed_dates||[]).includes(ds)){ if(noon.getTime()<=we.getTime()+DAY/2) closed_days.push({ date:ds, label:fmtDay.format(noon) }); continue; }
  const o=hrow.open_time.split(':').map(Number), c=hrow.close_time.split(':').map(Number);
  let n=0;
  for(let m=o[0]*60+o[1]; m+SLOT_H*60<=c[0]*60+c[1]; m+=SLOT_H*60){
    const s=toUtc(p.y,p.m,p.d,Math.floor(m/60),m%60); const e=new Date(s.getTime()+SLOT_H*3600000);
    if(s<ws||s>we) continue;
    const free=eligible.filter(t=>!busy(t.id,s,e));
    if(!free.length) continue;
    total++;
    if(n<PER_DAY&&slots.length<MAX_SLOTS){ n++; slots.push({ start:s.toISOString(), end:e.toISOString(), local_label:fmtDay.format(s)+', '+fmtTime.format(s)+'-'+fmtTime.format(e), technician_id:free[0].id, technician_name:free[0].name, techs_available:free.length }); }
  }
}
return JSON.stringify({ timezone:TZ, now_local:fmtDay.format(now)+', '+fmtTime.format(now), window:{ start:ws.toISOString(), end:we.toISOString() }, category:cat, slots, more_slots_not_shown:Math.max(0,total-slots.length), closed_days, closed_day: total===0&&closed_days.length>0, note:'These are the ONLY open slots. Quote times exactly as local_label (business local time). Never offer any day or time not listed here.' });

