const SLOT_H=2;
const dtf=new Intl.DateTimeFormat('en-US',{timeZone:TZ,hourCycle:'h23',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'});
const offMin=(d)=>{ const p={}; for(const x of dtf.formatToParts(d)) p[x.type]=x.value; return (Date.UTC(+p.year,+p.month-1,+p.day,(+p.hour)%24,+p.minute,+p.second)-Math.floor(d.getTime()/1000)*1000)/60000; };
const toUtc=(y,m,d,h,mi)=>{ const g=new Date(Date.UTC(y,m,d,h,mi)); const r=new Date(g.getTime()-offMin(g)*60000); return new Date(g.getTime()-offMin(r)*60000); };
const parseTs=(v)=>{ if(!v) return null; const s=String(v).trim(); const m=s.match(/^(\d{4})-(\d{2})-(\d{2})[T ](\d{1,2}):(\d{2})(?::\d{2}(?:\.\d+)?)?$/); if(m) return toUtc(+m[1],+m[2]-1,+m[3],+m[4],+m[5]); const d=new Date(s); return isNaN(d.getTime())?null:d; };
const fmt=new Intl.DateTimeFormat('en-US',{timeZone:TZ,weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
// --- readback gate ---
const rb=pick('confirmed_readback','confirmed','readback_confirmed');
