// --- write ---
const appt=await post('appointments',{ org_id:org, end_customer_id:cust.id, service_id, technician_id:tech.id, scheduled_at:start.toISOString(), arrival_window:pick('arrival_window')||null, price:pick('price')||null, status:'booked', recurrence:pick('recurrence')||'none', waitlist:!!pick('waitlist'), notes:pick('notes')||null, source_conversation_id:ctx.conversation_id });
