const SB=$env.SUPABASE_URL+'/rest/v1/';
const HW={ apikey:$env.SUPABASE_SERVICE_ROLE_KEY, Authorization:'Bearer '+$env.SUPABASE_SERVICE_ROLE_KEY, 'Content-Type':'application/json', Prefer:'return=representation' };
