const notify=async(kind,ref)=>{ try{ await post('notifications',{ org_id:org, channel:'owner', kind, ref_id:ref }); return kind; }catch(e){ try{ await post('notifications',{ org_id:org, channel:'owner', kind:'new_booking', ref_id:ref }); return 'new_booking (fallback: notification kind "'+kind+'" not allowed by the database yet)'; }catch(e2){ return 'failed'; } } };
const appendNote=(old,line)=>(old?String(old)+String.fromCharCode(10):'')+'['+new Date().toISOString().slice(0,16)+'Z] '+line;
const out=(o)=>JSON.stringify(o);
// ---- cancel_appointment ----
const own=await loadOwned(pick('appointment_id','id'));
if(own.err) return out(own.err);
const appt=own.appt;
if(appt.status==='cancelled') return out({ appointment_id:appt.id, status:'cancelled', already_cancelled:true, detail:'This appointment was already cancelled.' });
if(!['booked','requested'].includes(appt.status)) return out({ error:'not_active', detail:'This appointment is '+appt.status+' and cannot be cancelled here. Offer to connect the customer with a person.' });
const when=new Date(appt.scheduled_at);
const reason=pick('reason','cancel_reason','notes')||null;
// read-back gate (enforced here, not trusted from the model)
const prev=lastAssistant(); const msg=String(ctx.message_text||'');
const readback='Just to confirm, you want to cancel your '+svcName(appt.service_id)+' appointment on '+slotLabel(when)+'? Reply YES to cancel.';
const gateOk=AFFIRM.test(msg)&&ASKS_YES.test(prev)&&/cancel/i.test(prev)&&mentionsDate(prev,when);
if(!gateOk) return out({ error:'readback_required', changed:false, detail:'Nothing was cancelled. Send the customer this confirmation as your reply, then call cancel_appointment again after they reply yes. Pass the reason they gave.', readback });
await patch('appointments?id=eq.'+appt.id+'&org_id=eq.'+org,{ status:'cancelled', notes:appendNote(appt.notes,'Cancelled by customer via SMS'+(reason?': '+reason:'')) });
const n=await notify('cancellation',appt.id);
return out({ appointment_id:appt.id, status:'cancelled', cancelled_local_label:slotLabel(when), reason, owner_notified:n, next_step:'Confirm the cancellation and offer to rebook.' });

